def transform(grid):
    """Transform grid: replace 4s with spreading pattern"""
    h, w = len(grid), len(grid[0])

    # Find barrier row
    barrier_row = None
    for r in range(h):
        if any(v == 2 for v in grid[r]):
            barrier_row = r
            break

    result = [[0]*w for _ in range(h)]

    # Copy the barrier
    if barrier_row is not None:
        for c in range(w):
            result[barrier_row][c] = grid[barrier_row][c]

    # For each 4 in input
    for r0, c0 in [(r,c) for r, row in enumerate(grid) for c, val in enumerate(row) if val == 4]:

        # Determine exploration range based on distance to barrier
        dist_to_barrier = barrier_row - r0  # positive if barrier is below

        # Rows going UP (away from barrier) - always go 1 row up
        max_up = 1
        for dr_up in range(max_up):
            row_idx = r0 - dr_up - 1  # going up means negative row change
            abs_dr = dr_up

            # Width decreases as we go further up: hw = max(0, 2 - abs_dr)
            hw = max(0, 2 - abs_dr)

            left = c0 - hw
            right = c0 + hw

            if 0 <= row_idx < h:
                for c in range(left, right + 1):
                    if 0 <= c < w:
                        result[row_idx][c] = 4

        # Rows going DOWN (toward and through barrier side)
        # Sequence of half-widths: start=0, then 1, then 2, then 1, then 0, ... 
        # Going up from barrier: [0,1,2,1,0,...]

        hw_seq = []
        d = 0
        while True:
            if d > 10: break  # safety
            if d == 0:
                hw = 0
            elif d == 1:
                hw = 1
            elif d == 2:
                hw = 2
            elif d == 3:
                hw = 1
            else:
                hw = 0
            hw_seq.append(hw)
            d += 1

        for d, hw in enumerate(hw_seq):
            row_idx = r0 + d

            if row_idx > barrier_row:
                break

            left = c0 - hw
            right = c0 + hw

            if 0 <= row_idx < h:
                for c in range(left, right + 1):
                    if 0 <= c < w:
                        result[row_idx][c] = 4

    return result

