def transform(grid):
    """Transform grid with ray-based spreading from 4s"""
    h, w = len(grid), len(grid[0])

    # Find barrier row
    barrier_row = None
    for r in range(h):
        if any(v == 2 for v in grid[r]):
            barrier_row = r
            break

    result = [[0]*w for _ in range(h)]

    # Copy the barrier
    if barrier_row is not None:
        for c in range(w):
            result[barrier_row][c] = grid[barrier_row][c]

    # For each 4 in input
    for r0, c0 in [(r,c) for r, row in enumerate(grid) for c, val in enumerate(row) if val == 4]:

        dist_to_barrier = barrier_row - r0

        # Determine which cells will receive 4s from this source
        # Each source emits rays in 8 directions

        # Rays going AWAY from barrier (increasing distance)
        if dist_to_barrier > 0:
            # Barrier BELOW: up is away, down is toward
            # Going UP (away): d = -1, -2, ... max 2 steps
            for d in [-1, -2]:
                row_idx = r0 + d
                if row_idx < 0: break

                # Calculate half-width based on distance from source
                abs_d = -d  # = 1, 2

                # Pattern: at |d|=1: fill edges; at |d|=2: fill one column
                if abs_d == 1:
                    # Fill left edge and right edge
                    left = c0 - 2
                    right = c0 + 2
                    if 0 <= row_idx < h and 0 <= left < w:
                        result[row_idx][left] = 4
                    if 0 <= row_idx < h and 0 <= right < w:
                        result[row_idx][right] = 4
                elif abs_d == 2:
                    # Fill center
                    if 0 <= row_idx < h and 0 <= c0 < w:
                        result[row_idx][c0] = 4

            # Going DOWN (toward): d = 0, 1, ... until just before barrier
            for d in [0, 1, 2]:
                row_idx = r0 + d
                if row_idx >= barrier_row: break

                if d == 0:
                    # Same row: fill immediate neighbors
                    left = c0 - 1
                    right = c0 + 1
                    if 0 <= row_idx < h:
                        if 0 <= left < w: result[row_idx][left] = 4
                        if 0 <= right < w: result[row_idx][right] = 4
                elif d == 1:
                    # One row below: fill center
                    if 0 <= row_idx < h and 0 <= c0 < w:
                        result[row_idx][c0] = 4
                # d >= 2: already hit barrier or would hit it

        elif dist_to_barrier < 0:
            # Barrier ABOVE: opposite logic
            # Going DOWN (away): similar to up when barrier below
            d = 1
            abs_d = d
            if abs_d == 1:
                left = c0 - 2
                right = c0 + 2
                row_idx = r0 + d
                if 0 <= row_idx < h and 0 <= left < w:
                    result[row_idx][left] = 4
                if 0 <= row_idx < h and 0 <= right < w:
                    result[row_idx][right] = 4
            elif abs_d == 2:
                if 0 <= row_idx < h and 0 <= c0 < w:
                    result[row_idx][c0] = 4

            # Going UP (toward barrier): d = 0, -1, ...
            for d in [0, -1, -2]:
                row_idx = r0 + d
                if row_idx <= barrier_row: break

                if d == 0:
                    left = c0 - 1
                    right = c0 + 1
                    if 0 <= row_idx < h:
                        if 0 <= left < w: result[row_idx][left] = 4
                        if 0 <= right < w: result[row_idx][right] = 4
                elif d == -1:
                    if 0 <= row_idx < h and 0 <= c0 < w:
                        result[row_idx][c0] = 4
                elif d == -2:
                    # Two rows above: fill edges
                    left = c0 - 2
                    right = c0 + 2
                    if 0 <= row_idx < h and 0 <= left < w:
                        result[row_idx][left] = 4
                    if 0 <= row_idx < h and 0 <= right < w:
                        result[row_idx][right] = 4
        else:
            # On barrier - no spread
            pass

    return result

