def transform_v4(grid):
    """Transform using even/odd column spreading"""
    h, w = len(grid), len(grid[0])

    # Find barrier row
    barrier_row = None
    for r in range(h):
        if any(v == 2 for v in grid[r]):
            barrier_row = r
            break

    result = [[0]*w for _ in range(h)]

    # Copy the barrier
    if barrier_row is not None:
        for c in range(w):
            result[barrier_row][c] = grid[barrier_row][c]

    # For each 4 in input
    for r0, c0 in [(r,c) for r, row in enumerate(grid) for c, val in enumerate(row) if val == 4]:

        dist_to_barrier = barrier_row - r0

        # Check if we're above the barrier
        if barrier_row > r0:
            # Going UP: spread every other column starting from c0

            # First row up (r0-1): fill c0±1, skipping if out of bounds
            r = r0 - 1
            for dc in [-1, 1]:
                c = c0 + dc
                if 0 <= c < w:
                    result[r][c] = 4

            # Second row up (r0-2): fill c0±2
            r = r0 - 2
            for dc in [-2, 2]:
                c = c0 + dc
                if 0 <= c < w:
                    result[r][c] = 4

            # Third row up: would fill c0±3, but cap at ±2
            r = r0 - 3
            for dc in [-2, 2]:  # capped at 2
                c = c0 + dc
                if 0 <= c < w:
                    result[r][c] = 4

            # Going DOWN toward barrier
            for dr in [1, 2, 3]:
                r = r0 + dr

                if r >= barrier_row:
                    break

                # Each step down fills just the center column
                if 0 <= c0 < w:
                    result[r][c0] = 4

        elif barrier_row < r0:
            # Barrier above: opposite direction
            # Going DOWN (away): similar pattern
            r = r0 + 1
            for dc in [-1, 1]:
                c = c0 + dc
                if 0 <= c < w:
                    result[r][c] = 4

            r = r0 + 2
            for dc in [-2, 2]:
                c = c0 + dc
                if 0 <= c < w:
                    result[r][c] = 4

            # Going UP toward barrier
            for dr in [1, 2]:
                r = r0 - dr
                if r <= barrier_row: break
                if 0 <= c0 < w:
                    result[r][c0] = 4

    return result

