            offsets = [(-1, -2), (-1, +2), (0, -1), (0, +1), (+1, 0)]

            for dr, dc in offsets:
                r = r0 + dr
                c = c0 + dc

                if 0 <= r < h and 0 <= c < w and r != barrier_row:
